        if (!UserManager.isValidEmail(email)) {
            throw new Error('Invalid email format');
        }

        if (!UserManager.isValidAge(age)) {
            throw new Error('Age must be a positive integer');
        }

        const newUser = {
            id: this.nextId++,
            name,
            email,
            age
        };

        this.users.push(newUser);
        return newUser;
    }

    // Retrieve a user by their ID
    getUserById(id) {
        const user = this.users.find(user => user.id === id);
        if (!user) {
            throw new Error('User not found');
        }
        return user;
    }

    // Update user information
    updateUser(id, updates) {
        const user = this.getUserById(id); // This will throw if user not found

        const { name, email, age } = updates;

        if (email && !UserManager.isValidEmail(email)) {
            throw new Error('Invalid email format');
        }

        if (age && !UserManager.isValidAge(age)) {
            throw new Error('Age must be a positive integer');
        }

        if (name !== undefined) user.name = name;
        if (email !== undefined) user.email = email;
        if (age !== undefined) user.age = age;

        return user;
    }

    // Delete a user by their ID
    deleteUser(id) {
        const index = this.users.findIndex(user => user.id === id);
        if (index === -1) {
             throw new Error('User not found');
        }
        this.users.splice(index, 1);
        return true;
    }

    // Retrieve all users
    getAllUsers() {
        return this.users;
    }
}

